set-variable.value:
@{
      string digest = context.Request.Headers.GetValueOrDefault("Digest", "");
      string jws = context.Request.Headers.GetValueOrDefault("x-jws-signature", "");
      if (string.IsNullOrEmpty(digest)) { return "Header 'Digest' is required."; }
      if (string.IsNullOrEmpty(jws)) { return "Header 'x-jws-signature' is required."; }
      return "";
    }
